// Parse incoming VAPI request and extract toolCallId
const body = $input.item.json.body;
const message = body.message;
const toolWithToolCallList = message.toolWithToolCallList || [];
const toolCall = toolWithToolCallList[0]?.toolCall;

if (!toolCall) {
  return [{
    json: {
      error: true,
      message: "No tool call found",
      results: [{
        toolCallId: 'unknown',
        error: 'No tool call found in request'
      }]
    }
  }];
}

const args = toolCall.function.arguments;
const toolCallId = toolCall.id;

const barberCalendars = {
  "Ania": "cal-3b99b575@group.calendar.google.com",
  "Borys": "cal-a5a747c6@group.calendar.google.com",
  "Andrzej": "cal-5052a5da@group.calendar.google.com",
  "Bartek": "cal-1192ec64@group.calendar.google.com",
  "Magda": "cal-5465f5f8@group.calendar.google.com"
};

const serviceDurations = {"Strzyżenie krótkie": 60, "Strzyżenie średnie": 60, "Strzyżenie długie": 90, "Maszynką": 30, "Broda": 30, "Strzyżenie brody": 30, "Golenie": 60, "Combo": 90, "Repigmentacja": 60, "Koloryzacja": 90};

function normalizePhone(phone) {
  if (!phone) return null;
  const digits = phone.replace(/\D/g, '');
  if (digits.length === 9) return '+48' + digits;
  if (digits.length === 11 && digits.startsWith('48')) return '+' + digits;
  if (digits.length === 12 && phone.startsWith('+48')) return phone;
  return null;
}

function isValidEmail(email) {
  if (!email) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

const request = args.Request;
const barberName = args.Barber;
const service = args.Usluga;
const date = args.Data_Wizyty;
const time = args.Godzina_Wizyty;
const name = args.Imie_Nazwisko;
const email = args.Adres_Email;
const phone = args.Numer_Telefonu;
const calendarId = barberName ? barberCalendars[barberName] : null;
const duration = service ? serviceDurations[service] : 60;
const normalizedPhone = normalizePhone(phone);
const emailValid = isValidEmail(email);
const errors = [];

if (request === 'Rezerwacja_Wizyty') {
  if (!name || name.split(' ').length < 2) errors.push('Imię i nazwisko wymagane');
  if (!emailValid) errors.push('Nieprawidłowy email');
  if (!normalizedPhone) errors.push('Nieprawidłowy telefon');
  if (!barberName) errors.push('Barber wymagany');
  if (!service) errors.push('Usługa wymagana');
  if (!date) errors.push('Data wymagana');
  if (!time) errors.push('Godzina wymagana');
}

if (request === 'Znajdz_Rezerwacje' || request === 'Anuluj_Rezerwacje') {
  if (!name) errors.push('Imię wymagane');
  if (!emailValid) errors.push('Nieprawidłowy email');
}

return [{json: {request, barberName, calendarId, service, duration, date, time, name, email, emailValid, phone: normalizedPhone, toolCallId, errors, hasErrors: errors.length > 0, allBarbers: Object.keys(barberCalendars), barberCalendars, body}}];

const errors = $input.item.json.errors || [];
const toolCallId = $input.item.json.toolCallId || 'unknown';
return [{json: {results: [{toolCallId, result: `Błąd: ${errors.join(', ')}`}]}}];

const {date, time, barberName, calendarId, service, duration, toolCallId} = $input.item.json;
if (!barberName || !date || !time) return [{json: {error: true, results: [{toolCallId, result: "Proszę podać barbera, datę i godzinę"}]}}];
const startDateTime = new Date(`${date}T${time}:00`);
const endDateTime = new Date(startDateTime.getTime() + duration * 60000);
const endTime = endDateTime.toTimeString().split(' ')[0].substring(0, 5);
const endDateTimeISO = endDateTime.toISOString().split('.')[0];
return [{json: {error: false, searchMode: 'check_specific', calendarId, barberName, date, time, endTime, endDateTime: endDateTimeISO, service, duration, toolCallId}}];

const {service, duration, toolCallId, barberCalendars} = $input.item.json;
const now = new Date();
const startDate = now.toISOString().split('T')[0];
const startTime = now.toTimeString().split(' ')[0].substring(0, 5);
const businessHours = {1:{start:'09:00',end:'19:00'},2:{start:'09:00',end:'19:00'},3:{start:'09:00',end:'21:00'},4:{start:'09:00',end:'21:00'},5:{start:'09:00',end:'21:00'},6:{start:'09:00',end:'21:00'},0:{start:'10:00',end:'19:00'}};
return [{json: {searchMode: 'find_next_slots', service: service || 'Strzyżenie krótkie', duration, toolCallId, startDate, startTime, businessHours, barberCalendars, barbersToCheck: Object.keys(barberCalendars), slotsFound: [], maxSlots: 3}}];

const {date, time, duration, barberName, calendarId, service, name, email, phone, toolCallId} = $input.item.json;
const startDateTime = new Date(`${date}T${time}:00`);
const endDateTime = new Date(startDateTime.getTime() + duration * 60000);
const endTime = endDateTime.toTimeString().split(' ')[0].substring(0, 5);
const endDateTimeISO = endDateTime.toISOString().split('.')[0];
return [{json: {calendarId, barberName, service, date, time, endTime, endDateTime: endDateTimeISO, duration, name, email, phone, toolCallId, summary: `${service} - ${name}`}}];

const {name, email, toolCallId, barberCalendars} = $input.item.json;
const calendars = Object.entries(barberCalendars).map(([barber, calId]) => ({barber, calendarId: calId, name, email, toolCallId}));
return calendars.map(cal => ({json: cal}));

const toolCallId = $input.first().json.toolCallId;
const allEvents = $input.all();
const validEvents = allEvents.filter(e => e.json.id && e.json.summary);
if (validEvents.length === 0) return [{json: {results: [{toolCallId, result: "Nie znaleziono rezerwacji"}]}}];
const booking = validEvents[0].json;
const summary = booking.summary;
const startTime = booking.start?.dateTime || booking.start?.date;
return [{json: {results: [{toolCallId, result: `Znaleziono: ${summary}, ${startTime}`}]}}];

const {name, email, toolCallId, barberCalendars} = $input.item.json;
const calendars = Object.entries(barberCalendars).map(([barber, calId]) => ({barber, calendarId: calId, name, email, toolCallId}));
return calendars.map(cal => ({json: cal}));

const toolCallId = $input.first().json.toolCallId;
const deleted = $input.all().length > 0;
const msg = deleted ? "Wizyta anulowana" : "Nie znaleziono wizyty";
return [{json: {results: [{toolCallId, result: msg}]}}];

const events = $input.all();
const {barberName, date, time, service, toolCallId} = $input.first().json;
const validEvents = events.filter(e => e.json.id);
const msg = validEvents.length > 0 ? `Zajęte. ${barberName} niedostępny ${date} o ${time}` : `Wolne! ${barberName} dostępny ${date} o ${time} na ${service}`;
return [{json: {results: [{toolCallId, result: msg}]}}];
